const calculateTiempoEstimadoAuto = (item: Partial<DemandaItem>): string => {
  if (item.tiempoEstimadoCompleto) return item.tiempoEstimadoCompleto;
  if (item.planificacionEstimada && item.fechaEstimadaEntrega) {
    const inicio = new Date(item.planificacionEstimada);
    const entrega = new Date(item.fechaEstimadaEntrega);
    if (!isNaN(inicio.getTime()) && !isNaN(entrega.getTime())) {
      const diffTime = entrega.getTime() - inicio.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 0) {
        if (diffDays >= 30) {
          const meses = (diffDays / 30).toFixed(1).replace('.0', '');
          return `${diffDays} días (~${meses} ${meses === '1' ? 'mes' : 'meses'})`;
        }
        return `${diffDays} días`;
      }
    }
  }
  return '-';
};

const generateProjectCode = (nombre: string, existingItems: DemandaItem[], currentId?: string | null): string => {
  if (!nombre || !nombre.trim()) return '';
  const clean = nombre.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, '');
  const prefix = clean.substring(0, 4);
  if (!prefix) return '';

  const matchingCodes = (existingItems || [])
    .filter(item => item.id !== currentId && item.codigo && item.codigo.toLowerCase().startsWith(`${prefix}_`))
    .map(item => {
      const parts = (item.codigo || '').split('_');
      return parts.length > 1 ? parseInt(parts[1], 10) : 0;
    })
    .filter(n => !isNaN(n));

  const maxNum = matchingCodes.length > 0 ? Math.max(...matchingCodes) : 0;
  const nextNum = maxNum + 1;
  const numStr = nextNum.toString().padStart(2, '0');
  return `${prefix}_${numStr}`;
};

